STOCK_GUARD = """
CREATE FUNCTION phc_guard_stock_movement() RETURNS trigger AS $$
DECLARE current_quantity bigint;
BEGIN
    PERFORM id FROM phc_inventory_item WHERE id = NEW.item_id FOR UPDATE;
    SELECT COALESCE(SUM(quantity_delta), 0) INTO current_quantity
      FROM phc_inventory_movement WHERE item_id = NEW.item_id;
    IF current_quantity + NEW.quantity_delta < 0 THEN
        RAISE EXCEPTION 'PHC stock quantity cannot be negative';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER phc_stock_nonnegative BEFORE INSERT ON phc_inventory_movement
FOR EACH ROW EXECUTE FUNCTION phc_guard_stock_movement();
"""

