SCHEDULE_RANGE = """
CREATE FUNCTION phc_set_week_range() RETURNS trigger AS $$
DECLARE start_minute integer; end_minute integer;
BEGIN
    start_minute := NEW.day_of_week * 1440
      + EXTRACT(HOUR FROM NEW.starts_at)::integer * 60
      + EXTRACT(MINUTE FROM NEW.starts_at)::integer;
    end_minute := NEW.day_of_week * 1440
      + EXTRACT(HOUR FROM NEW.ends_at)::integer * 60
      + EXTRACT(MINUTE FROM NEW.ends_at)::integer;
    IF NEW.day_of_week < 0 OR NEW.day_of_week > 6 OR end_minute <= start_minute THEN
        RAISE EXCEPTION 'PHC schedule slot time is invalid';
    END IF;
    NEW.week_range := int4range(start_minute, end_minute, '[)');
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER phc_schedule_range BEFORE INSERT OR UPDATE ON phc_doctor_schedule_slot
FOR EACH ROW EXECUTE FUNCTION phc_set_week_range();
"""

